// ===== STATE =====
var currentPage="dashboard",currentRegion="west",campaigns=[],uploadedVideos=[],clockInterval=null,liveTickerInterval=null,dashboardTimeRange="all",liveSpend=0,liveConv=0,liveStartTime=0;
// Load from localStorage
function loadState(){try{var d=JSON.parse(localStorage.getItem("dramaAdState"));if(d){campaigns=d.campaigns||[];uploadedVideos=d.uploadedVideos||[];ensureCampaignData();saveState()}else{initDefaultCampaigns()}}catch(e){initDefaultCampaigns()}}
loadState();
// Check URL params for TK popup trigger
var urlParams=new URLSearchParams(window.location.search);
if(urlParams.get("tk_popup")){tkRatingShown=false;}
function saveState(){try{localStorage.setItem("dramaAdState",JSON.stringify({campaigns:campaigns,uploadedVideos:uploadedVideos}))}catch(e){}}
function initDefaultCampaigns(){
  // 4 accounts, 4 dramas. All 45 episodes active. CPA $1-2.
  var accounts=[
    {dramaId:31,budget:9000,spend:2000,revenue:11110,profit:2110,profitRate:1,episodes:45,rating:"A"},
    {dramaId:32,budget:9600,spend:1000,revenue:10600,profit:1000,profitRate:0,episodes:45,rating:"B"},
    {dramaId:33,budget:22500,spend:1500,revenue:24225,profit:1725,profitRate:225,episodes:45,rating:"S"},
    {dramaId:34,budget:8000,spend:1200,revenue:9800,profit:1000,profitRate:0,episodes:45,rating:"A"}
  ];
  var platforms=["TikTok","YouTube Shorts","Instagram Reels"];
  var cpa=1.45;
  var id=1;
  // Wedding Swap: 55 episodes, explosive growth
  var weddingDramaId=35;
  var weddingBudget=6000;
  var weddingSpend=3011;
  var weddingConv=1302;
  var weddingConvTimes=2011;
  var weddingGmv=5099.60;
  var weddingImpr=1250000;
  var weddingCtr=14.56;
  var weddingPlatforms=["TikTok","Instagram Reels","YouTube Shorts"];
  var weddingCopy="#TheWeddingSwap #BillionaireRomance #ShortDrama #TikTokDrama #PlotTwist #MarryingRich #DramaSeries #MustWatch #WeddingBetrayal #RichHusband";
  var weddingVideoUrl="https://www.tiktok.com/@dramaadpro/video/7258000000000000000";
  // Wedding Swap: base per-episode metrics from real TikTok screenshot
  // base: impressions 156941, likes 12, comments 2, shares 17, saves 1, conversions 6, convTimes 9, gmv $18
  var wBase={impressions:156941,likes:12,comments:2,shares:17,saves:1,conversions:6,convTimes:9,gmv:18.00};
  function wJitter(base,pct,min){var v=Math.round(base*(1+(Math.random()*2-1)*pct));if(v<min)v=min;return v}
  for(var wi=1;wi<=55;wi++){
    var wScale=(wi<=15)?1:(0.6+Math.random()*0.2); // EP16+ slightly lower
    var wImpr=Math.round(wBase.impressions*wScale*(1+(Math.random()*2-1)*0.15));
    var wLikes=wJitter(wBase.likes*wScale,0.2,5);
    var wComments=Math.floor(Math.random()*6);
    var wShares=wJitter(wBase.shares*wScale,0.25,1);
    var wSaves=Math.floor(Math.random()*4);
    var wConv=wJitter(wBase.conversions*wScale,0.3,3);
    var wConvTimes=wJitter(wBase.convTimes*wScale,0.3,5);
    var wGmv=Math.max(8,Math.round((wBase.gmv*wScale+(Math.random()*6-3))*100)/100);
    var wSpend=Math.max(10,Math.round(wConv*2.7*100)/100);
    var wClicks=Math.floor(wImpr*weddingCtr/100);
    campaigns.push({
      id:id++,dramaId:weddingDramaId,
      name:"EP"+wi,nameZh:"第"+wi+"集",
      region:"west",budget:15,spend:wSpend,
      status:"active",
      impressions:wImpr,clicks:wClicks,
      conversions:wConv,
      buyers:wConv,
      likes:wLikes,comments:wComments,shares:wShares,saves:wSaves,
      platform:weddingPlatforms[wi%3],
      adCopy:weddingCopy,coverUrl:"",episode:wi,
      accountId:1,rating:"S",
      videoUrl:weddingVideoUrl,
      convTimes:wConvTimes,gmv:wGmv,
      ctr:weddingCtr
    });
  }
  accounts.forEach(function(acc,ai){
    var perEpBudget=Math.floor(acc.budget/acc.episodes);
    var perEpSpend=Math.floor(acc.spend/acc.episodes);
    for(var i=1;i<=acc.episodes;i++){
      var epSpend=perEpSpend+Math.floor(Math.random()*20-10);
      if(epSpend<5)epSpend=5;
      var epBuyers=Math.floor(epSpend/cpa);
      var impressions=Math.floor(epSpend*(Math.random()*400+2600));
      campaigns.push({
        id:id++,dramaId:acc.dramaId,
        name:"EP"+i,nameZh:"第"+i+"集",
        region:"west",budget:perEpBudget,spend:epSpend,
        status:"active",
        impressions:impressions,clicks:Math.floor(impressions*(Math.random()*0.03+0.02)),
        conversions:Math.floor(epBuyers*(Math.random()*0.3+0.2)),
        buyers:epBuyers,
        platform:platforms[ai%3],
        adCopy:"",coverUrl:"",episode:i,
        accountId:ai+1,rating:acc.rating
      });
    }
  });
  ensureCampaignData();
  saveState();
}
// ===== Ensure top in-flight dramas + 10 paused dramas exist (migration-safe) =====
function ensureCampaignData(){
  var existingDramaIds={};
  campaigns.forEach(function(c){existingDramaIds[c.dramaId]=true});
  var platforms=["TikTok","YouTube Shorts","Instagram Reels"];
  var nextId=(campaigns.length?campaigns.reduce(function(m,c){return Math.max(m,c.id)},0):0)+1;
  function pushEpisodes(dramaId,epCount,budget,spend,cpa,rating,status){
    if(existingDramaIds[dramaId])return;
    var perEpSpend=Math.round(spend/epCount*100)/100;
    var perEpBudget=Math.floor(budget/epCount);
    for(var i=1;i<=epCount;i++){
      var es=Math.max(5,Math.round((perEpSpend+Math.random()*10-5)*100)/100);
      var eb=Math.floor(es/cpa);
      if(eb<1)eb=1;
      var impr=Math.floor(es*(Math.random()*400+2600));
      var eLikes=Math.max(1,Math.floor(impr*0.038));
      var eComments=Math.max(1,Math.floor(eLikes*0.052));
      var eShares=Math.max(1,Math.floor(eLikes*0.098));
      var eSaves=Math.max(1,Math.floor(eLikes*0.065));
      campaigns.push({
        id:nextId++,dramaId:dramaId,
        name:"EP"+i,nameZh:"第"+i+"集",
        region:"west",budget:perEpBudget,spend:es,
        status:status,
        impressions:impr,clicks:Math.floor(impr*(Math.random()*0.03+0.02)),
        conversions:Math.floor(eb*(Math.random()*0.3+0.2)),
        buyers:eb,
        likes:eLikes,comments:eComments,shares:eShares,saves:eSaves,
        platform:platforms[i%3],
        adCopy:"",coverUrl:"",episode:i,
        accountId:1,rating:rating,
        videoUrl:"https://www.tiktok.com/@dramaadpro/video/7258000000000000000"
      });
    }
  }
  // 12 additional in-flight dramas (top performers)
  var extraActive=[
    {dramaId:97,episodes:58,budget:8000,spend:4200,cpa:1.9,rating:"S"},
    {dramaId:37,episodes:74,budget:9000,spend:3600,cpa:1.8,rating:"S"},
    {dramaId:36,episodes:45,budget:7000,spend:2800,cpa:2.0,rating:"A"},
    {dramaId:39,episodes:28,budget:6000,spend:2400,cpa:1.9,rating:"A"},
    {dramaId:40,episodes:32,budget:5500,spend:2100,cpa:2.1,rating:"A"},
    {dramaId:42,episodes:35,budget:5200,spend:1900,cpa:2.2,rating:"B"},
    {dramaId:47,episodes:25,budget:5000,spend:1700,cpa:2.1,rating:"B"},
    {dramaId:49,episodes:28,budget:4800,spend:1500,cpa:2.3,rating:"B"},
    {dramaId:52,episodes:30,budget:4600,spend:1300,cpa:2.2,rating:"B"},
    {dramaId:58,episodes:20,budget:4400,spend:1200,cpa:2.4,rating:"B"},
    {dramaId:67,episodes:24,budget:4200,spend:1100,cpa:2.3,rating:"B"},
    {dramaId:68,episodes:20,budget:4000,spend:1000,cpa:2.5,rating:"B"}
  ];
  extraActive.forEach(function(ea){pushEpisodes(ea.dramaId,ea.episodes,ea.budget,ea.spend,ea.cpa,ea.rating,"active")});
  // 10 paused dramas (id 1-25) with historical non-zero data
  var pausedPool=[1,2,3,7,8,9,10,11,12,13,16,17,20,21,24,25];
  pausedPool.sort(function(){return Math.random()-0.5});
  var pausedPick=pausedPool.slice(0,10);
  pausedPick.forEach(function(pid){
    var d=DRAMAS.find(function(dd){return dd.id===pid});
    if(!d)return;
    var epCount=Math.min(d.episodes||20,20);
    var totalSpend=800+Math.floor(Math.random()*1200);
    pushEpisodes(pid,epCount,400,totalSpend,2.2,"B","paused");
  });
  // Migrate: ensure all campaigns have non-zero social metrics
  campaigns.forEach(function(c){
    if(!c.likes||c.likes<1){c.likes=Math.max(1,Math.floor((c.impressions||1000)*0.038))}
    if(!c.comments||c.comments<1){c.comments=Math.max(1,Math.floor((c.likes||12)*0.052))}
    if(!c.shares||c.shares<1){c.shares=Math.max(1,Math.floor((c.likes||12)*0.098))}
    if(!c.saves||c.saves<1){c.saves=Math.max(1,Math.floor((c.likes||12)*0.065))}
    if(!c.conversions||c.conversions<1){c.conversions=Math.max(1,Math.floor((c.buyers||1)*0.8))}
    if(!c.convTimes||c.convTimes<1){c.convTimes=Math.max(1,Math.floor((c.conversions||3)*1.5))}
    if(!c.gmv||c.gmv<1){c.gmv=Math.max(1,Math.round((c.spend||15)*1.2*100)/100)}
    if(!c.buyers||c.buyers<1){c.buyers=Math.max(1,c.conversions||1)}
    if(!c.ctr){c.ctr=14.56}
    if(!c.spend||c.spend<0.01){c.spend=Math.max(2.5,Math.round((c.conversions||1)*2.7*100)/100)}
    if(!c.budget||c.budget<1){c.budget=15}
    if(!c.impressions||c.impressions<1){c.impressions=9088}
    if(!c.clicks||c.clicks<1){c.clicks=Math.floor((c.impressions||9088)*0.1456)}
    if(!c.videoUrl){c.videoUrl="https://www.tiktok.com/@dramaadpro/video/7258000000000000000"}
  })
  saveState()
}

