function startClocks(){if(clockInterval)return;function update(){var now=new Date();var zones=[{city:"北京",tz:"Asia/Shanghai"},{city:"洛杉矶",tz:"America/Los_Angeles"},{city:"纽约",tz:"America/New_York"},{city:"迪拜",tz:"Asia/Dubai"},{city:"曼谷",tz:"Asia/Bangkok"},{city:"东京",tz:"Asia/Tokyo"},{city:"孟买",tz:"Asia/Kolkata"}];zones.forEach(function(z,i){var opts={timeZone:z.tz,hour:"2-digit",minute:"2-digit",hour12:false};var timeEl=document.getElementById("tz-time-"+i);if(timeEl)timeEl.textContent=now.toLocaleTimeString("en-US",opts)})}update();clockInterval=setInterval(update,1000)}
// ===== LIVE MICRO-SPEND TICKER =====
function startLiveTicker(){
  if(liveTickerInterval)return;
  liveStartTime=Date.now();
  // Load persisted values from sessionStorage
  try{var saved=JSON.parse(sessionStorage.getItem("liveTickerState"));if(saved){liveSpend=saved.spend||0;liveConv=saved.conv||0}}catch(e){}
  function updateLive(){
    liveSpend+=0.007;
    // Random conversion every ~15 ticks (45s avg)
    if(Math.random()<0.07){liveConv+=1;addLiveFeed()}
    sessionStorage.setItem("liveTickerState",JSON.stringify({spend:liveSpend,conv:liveConv}));
    var elapsed=Math.floor((Date.now()-liveStartTime)/1000);
    var h=Math.floor(elapsed/3600),m=Math.floor((elapsed%3600)/60),s=elapsed%60;
    var timeStr=(h<10?"0"+h:h)+":"+(m<10?"0"+m:m)+":"+(s<10?"0"+s:s);
    var cpa=liveConv>0?(liveSpend/liveConv).toFixed(3):"0.000";
    var spendEl=document.getElementById("liveSpend");if(spendEl)spendEl.textContent="$"+liveSpend.toFixed(3);
    var convEl=document.getElementById("liveConv");if(convEl)convEl.textContent=liveConv;
    var cpaEl=document.getElementById("liveCPA");if(cpaEl)cpaEl.textContent="$"+cpa;
    var timeEl=document.getElementById("liveRuntime");if(timeEl)timeEl.textContent=timeStr;
  }
  updateLive();
  liveTickerInterval=setInterval(updateLive,3000);
}
function addLiveFeed(){
  var feed=document.getElementById("liveFeed");if(!feed)return;
  var d=new Date();var ts=d.getHours()+":"+(d.getMinutes()<10?"0":"")+d.getMinutes()+":"+(d.getSeconds()<10?"0":"")+d.getSeconds();
  var msgs=["用户转化 +1 · TikTok 美国","新付费用户 · Instagram Reels","解锁剧集 · YouTube Shorts","新订单 · TikTok 欧美","转化成功 · Facebook Reels"];
  var msg=msgs[Math.floor(Math.random()*msgs.length)];
  feed.innerHTML='<div style="color:var(--green);">['+ts+'] ✅ '+msg+'</div>'+feed.innerHTML;
  // Keep max 20 lines
  var lines=feed.querySelectorAll("div");if(lines.length>20)lines[lines.length-1].remove();
}

