function drawSeptChart(){
  var c=document.getElementById("septChart");
  if(!c)return;
  var ctx=c.getContext("2d");
  var W=c.width,H=c.height;
  ctx.clearRect(0,0,W,H);
  var data=[45,0,10,5,15,10,10];
  var labels=["9/1","9/2","9/3","9/4","9/5","9/6","9/7"];
  var cumData=[45,45,55,60,75,85,95];
  var maxVal=50;
  var padL=40,padR=15,padT=15,padB=30;
  var cw=W-padL-padR,ch=H-padT-padB;
  // Grid
  ctx.strokeStyle="#e0e0e0";ctx.lineWidth=1;ctx.font="9px sans-serif";ctx.fillStyle="#999";
  for(var i=0;i<=5;i++){var y=padT+ch*(1-i/5);ctx.beginPath();ctx.moveTo(padL,y);ctx.lineTo(W-padR,y);ctx.stroke();ctx.fillText((maxVal*i/5).toFixed(0),5,y+3)}
  // Bars (daily)
  var bw=cw/data.length;
  data.forEach(function(v,i){
    var x=padL+bw*i+bw*0.2;
    var bh=v/maxVal*ch;
    var y=padT+ch-bh;
    var grad=ctx.createLinearGradient(0,y,0,padT+ch);
    grad.addColorStop(0,"#1664ff");grad.addColorStop(1,"rgba(22,100,255,.3)");
    ctx.fillStyle=grad;
    ctx.fillRect(x,y,bw*0.6,bh);
    ctx.fillStyle="#1664ff";ctx.font="8px sans-serif";
    if(v>0)ctx.fillText(v,x+bw*0.3-5,y-3);
  });
  // Cumulative line
  ctx.strokeStyle="#00a870";ctx.lineWidth=2;ctx.beginPath();
  cumData.forEach(function(v,i){
    var x=padL+bw*i+bw*0.5;
    var y=padT+ch-(v/maxVal*ch);
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    // Draw point
    ctx.fillStyle="#00a870";ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();
  });
  ctx.stroke();
  // X labels
  ctx.fillStyle="#666";ctx.font="9px sans-serif";ctx.textAlign="center";
  labels.forEach(function(l,i){ctx.fillText(l,padL+bw*i+bw*0.5,H-10)});
  ctx.textAlign="left";
}

function handleSeptHover(e){
  var c=document.getElementById("septChart");
  if(!c)return;
  var rect=c.getBoundingClientRect();
  var x=(e.clientX-rect.left)*(c.width/rect.width);
  var data=[45,0,10,5,15,10,10];
  var labels=["9/1","9/2","9/3","9/4","9/5","9/6","9/7"];
  var cumData=[45,45,55,60,75,85,95];
  var padL=40,padR=15;
  var cw=c.width-padL-padR;
  var bw=cw/data.length;
  var idx=Math.floor((x-padL)/bw);
  if(idx<0||idx>=data.length)return;
  var tip=document.getElementById("septTooltip");
  if(!tip)return;
  tip.style.display="block";
  tip.style.left=(e.clientX-rect.left+10)+"px";
  tip.style.top=(e.clientY-rect.top-60)+"px";
  tip.innerHTML='<div style="font-weight:700;margin-bottom:4px;">'+labels[idx]+'</div><div style="color:var(--accent);">投流: '+data[idx]+' 条</div><div style="color:var(--green);">累计: '+cumData[idx]+' 条</div>';
}

