function drawTop5TrendChart(canvasId,series,colors){
  var c=document.getElementById(canvasId);
  if(!c)return;
  var ctx=c.getContext("2d");
  var W=c.width,H=c.height;
  ctx.clearRect(0,0,W,H);
  var maxVal=0;
  series.forEach(function(s){s.data.forEach(function(v){if(v>maxVal)maxVal=v})});
  maxVal=Math.ceil(maxVal/2500)*2500;
  var padL=36,padR=10,padT=10,padB=22;
  var cw=W-padL-padR,ch=H-padT-padB;
  var n=TOP5_LABELS.length;
  // Grid + Y axis labels (impressions)
  ctx.strokeStyle="#e0e0e0";ctx.lineWidth=1;ctx.font="8px sans-serif";ctx.fillStyle="#999";
  for(var i=0;i<=5;i++){
    var gy=padT+ch*(1-i/5);
    ctx.beginPath();ctx.moveTo(padL,gy);ctx.lineTo(W-padR,gy);ctx.stroke();
    ctx.fillText((maxVal*i/5).toFixed(0),3,gy+3);
  }
  // X axis labels
  ctx.fillStyle="#666";ctx.font="9px sans-serif";ctx.textAlign="center";
  TOP5_LABELS.forEach(function(l,i){ctx.fillText(l,padL+cw*i/(n-1),H-8)});
  ctx.textAlign="left";
  // Lines + data points
  series.forEach(function(s,si){
    ctx.strokeStyle=colors[si];ctx.lineWidth=2;ctx.beginPath();
    s.data.forEach(function(v,i){
      var x=padL+cw*i/(s.data.length-1);
      var y=padT+ch*(1-v/maxVal);
      if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    });
    ctx.stroke();
    ctx.fillStyle=colors[si];
    s.data.forEach(function(v,i){
      var x=padL+cw*i/(s.data.length-1);
      var y=padT+ch*(1-v/maxVal);
      ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();
    });
  });
}
function drawUsTop5Chart(){drawTop5TrendChart("usTop5Chart",US_TOP5_SERIES,US_TOP5_COLORS)}
function drawArabTop5Chart(){drawTop5TrendChart("arabTop5Chart",ARAB_TOP5_SERIES,ARAB_TOP5_COLORS)}
function handleTop5Hover(e,canvasId,tooltipId,series,colors){
  var c=document.getElementById(canvasId);
  if(!c)return;
  var rect=c.getBoundingClientRect();
  var x=(e.clientX-rect.left)*(c.width/rect.width);
  var n=TOP5_LABELS.length;
  var padL=36,padR=10;
  var cw=c.width-padL-padR;
  var idx=Math.round((x-padL)/cw*(n-1));
  if(idx<0||idx>=n)return;
  var tip=document.getElementById(tooltipId);
  if(!tip)return;
  tip.style.display="block";
  tip.style.left=Math.max(Math.min(e.clientX-rect.left+12,rect.width-185),0)+"px";
  tip.style.top=Math.max(e.clientY-rect.top-55,2)+"px";
  var html='<div style="font-weight:700;margin-bottom:4px;border-bottom:1px solid var(--border);padding-bottom:3px;">📅 '+TOP5_LABELS[idx]+' · 曝光量</div>';
  series.forEach(function(s,si){
    html+='<div style="display:flex;align-items:center;gap:4px;margin-bottom:2px;"><span style="width:8px;height:8px;border-radius:2px;background:'+colors[si]+';border:1px solid rgba(0,0,0,.1);display:inline-block;flex-shrink:0;"></span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:125px;">'+s.name+'</span><b style="margin-left:auto;padding-left:8px;">'+s.data[idx].toLocaleString()+'</b></div>';
  });
  tip.innerHTML=html;
}
