// ===== JIANZONG (剑宗团宠小师妹第五季) CHART =====
var JIANZONG_DATA={
  days:["9/5","9/6","9/7","9/8","9/9","9/10","9/11","9/12","9/13","9/14","9/15"],
  // Ad conversions (广告转化) - 9/5 peak, drop, then 9/13 recovery and stabilize
  conv:[109981,45200,8091,7200,6500,5800,6100,6800,8200,8100,8000],
  // Click count (点击次数)
  clicks:[20889341,5200000,907653,820000,750000,680000,720000,780000,920000,910000,900000],
  // Mini-program payments (小程序付费)
  pay:[2890,2650,3099,1850,1720,1580,1650,1780,2100,2080,2050]
};
function drawJianzongChart(){
  var c=document.getElementById("jianzongChart");
  if(!c)return;
  var ctx=c.getContext("2d");
  var W=c.width,H=c.height;
  var padL=45,padR=15,padT=15,padB=30;
  var cw=W-padL-padR,ch=H-padT-padB;
  ctx.clearRect(0,0,W,H);
  ctx.fillStyle="#fff";
  ctx.fillRect(0,0,W,H);
  var d=JIANZONG_DATA;
  var n=d.days.length;
  // Y axis: use log scale for conversions since range is huge
  var maxConv=109981,minConv=4000;
  var maxClicks=20889341,minClicks=480000;
  var maxPay=3099,minPay=1000;
  // Normalize each series to 0-1
  function norm(v,min,max){return Math.max(0,Math.min(1,(v-min)/(max-min)))}
  // Grid lines
  ctx.strokeStyle="#eee";
  ctx.lineWidth=0.5;
  ctx.font="8px sans-serif";
  ctx.fillStyle="#999";
  for(var i=0;i<=4;i++){
    var y=padT+(ch/4)*i;
    ctx.beginPath();ctx.moveTo(padL,y);ctx.lineTo(W-padR,y);ctx.stroke();
    var pct=100-i*25;
    ctx.fillText(pct+"%",2,y+3);
  }
  // X axis labels
  var xStep=cw/(n-1);
  ctx.fillStyle="#666";
  ctx.textAlign="center";
  for(var i=0;i<n;i++){
    var x=padL+xStep*i;
    ctx.fillText(d.days[i],x,H-8);
    // Tick mark
    ctx.strokeStyle="#ddd";
    ctx.beginPath();ctx.moveTo(x,padT+ch);ctx.lineTo(x,padT+ch+3);ctx.stroke();
  }
  // Peak zone highlight (9/5)
  var peakX=padL;
  var peakW=xStep*0.8;
  ctx.fillStyle="rgba(245,63,63,.06)";
  ctx.fillRect(peakX-peakW/2,padT,peakW,ch);
  ctx.strokeStyle="rgba(245,63,63,.2)";
  ctx.setLineDash([3,3]);
  ctx.beginPath();ctx.moveTo(peakX,padT);ctx.lineTo(peakX,padT+ch);ctx.stroke();
  ctx.setLineDash([]);
  // Peak annotation
  ctx.fillStyle="#f53f3f";
  ctx.font="bold 8px sans-serif";
  ctx.fillText("峰值 9/5 23:17",peakX+4,padT+10);
  // Draw conversions line (green)
  ctx.strokeStyle="#00a870";
  ctx.lineWidth=2;
  ctx.beginPath();
  for(var i=0;i<n;i++){
    var x=padL+xStep*i;
    var y=padT+ch-norm(d.conv[i],minConv,maxConv)*ch;
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
  }
  ctx.stroke();
  // Data points
  ctx.fillStyle="#00a870";
  for(var i=0;i<n;i++){
    var x=padL+xStep*i;
    var y=padT+ch-norm(d.conv[i],minConv,maxConv)*ch;
    ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();
  }
  // Draw clicks line (blue, scaled)
  ctx.strokeStyle="#1664ff";
  ctx.lineWidth=2;
  ctx.beginPath();
  for(var i=0;i<n;i++){
    var x=padL+xStep*i;
    var y=padT+ch-norm(d.clicks[i],minClicks,maxClicks)*ch;
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
  }
  ctx.stroke();
  ctx.fillStyle="#1664ff";
  for(var i=0;i<n;i++){
    var x=padL+xStep*i;
    var y=padT+ch-norm(d.clicks[i],minClicks,maxClicks)*ch;
    ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();
  }
  // Draw payments line (gold)
  ctx.strokeStyle="#f5a623";
  ctx.lineWidth=2;
  ctx.beginPath();
  for(var i=0;i<n;i++){
    var x=padL+xStep*i;
    var y=padT+ch-norm(d.pay[i],minPay,maxPay)*ch;
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
  }
  ctx.stroke();
  ctx.fillStyle="#f5a623";
  for(var i=0;i<n;i++){
    var x=padL+xStep*i;
    var y=padT+ch-norm(d.pay[i],minPay,maxPay)*ch;
    ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();
  }
  // Store coords for hover
  c._jzData={padL:padL,padR:padR,padT:padT,padB:padB,cw:cw,ch:ch,xStep:xStep,n:n,W:W,H:H};
}
function handleJianzongHover(e){
  var c=document.getElementById("jianzongChart");
  if(!c||!c._jzData)return;
  var rect=c.getBoundingClientRect();
  var scaleX=c.width/rect.width;
  var mx=(e.clientX-rect.left)*scaleX;
  var d=JIANZONG_DATA;
  var cd=c._jzData;
  var tip=document.getElementById("jianzongTooltip");
  if(!tip)return;
  // Find nearest point
  var idx=-1,minDist=999;
  for(var i=0;i<cd.n;i++){
    var x=cd.padL+cd.xStep*i;
    var dist=Math.abs(mx-x);
    if(dist<minDist){minDist=dist;idx=i}
  }
  if(idx<0||minDist>20){tip.style.display="none";return}
  var x=cd.padL+cd.xStep*idx;
  var convY=cd.padT+cd.ch-((d.conv[idx]-4000)/(109981-4000))*cd.ch;
  var clickY=cd.padT+cd.ch-((d.clicks[idx]-480000)/(20889341-480000))*cd.ch;
  var payY=cd.padT+cd.ch-((d.pay[idx]-1000)/(3099-1000))*cd.ch;
  tip.style.display="block";
  tip.style.left=(x*scaleX+10)+"px";
  tip.style.top=(cd.padT+10)+"px";
  tip.innerHTML='<div style="font-weight:700;margin-bottom:4px;">'+d.days[idx]+'</div>'+
    '<div style="color:#00a870;">🟢 广告转化: '+d.conv[idx].toLocaleString()+'</div>'+
    '<div style="color:#1664ff;">🔵 点击次数: '+d.clicks[idx].toLocaleString()+'</div>'+
    '<div style="color:#f5a623;">🟡 小程序付费: '+d.pay[idx].toLocaleString()+' 次</div>';
  if(idx===0)tip.innerHTML+='<div style="color:#f53f3f;font-weight:600;margin-top:3px;">⚡ 峰值时刻 23:17</div>';
}

