function closeTikTokModal(e){if(e&&e.target.className!=="tiktok-modal-overlay")return;var el=document.getElementById("tiktokModal");if(el)el.remove()}

// ===== DRAMA LIBRARY =====
function renderDramaLibrary(){
  var origins=["cn","us","ae","th","jp","in"];
  var originLabels={cn:"chinaDrama",us:"westernDrama",ae:"arabDrama",th:"thaiDrama",jp:"japanDrama",in:"indiaDrama"};
  var h="";
  origins.forEach(function(orig){
    var dramas=DRAMAS.filter(function(d){return d.origin===orig});
    h+='<div class="card"><div class="card-header"><div class="card-title">'+t(originLabels[orig])+' ('+dramas.length+')</div></div>';
    h+='<table class="drama-table"><thead><tr><th>'+t("dramaName")+'</th><th>'+t("typeLabel")+'</th><th>'+t("episodes")+'</th><th>'+t("totalViews")+'</th><th>'+t("regionStatus")+'</th><th>'+t("actions")+'</th></tr></thead><tbody>';
    dramas.forEach(function(d){
      var typeLabel=d.type==="real"?t("realPerson"):t("aiGenerated");
      var typeBadge=d.type==="real"?"type-real":"type-ai";
      h+='<tr><td><div style="display:flex;align-items:center;gap:6px;"><img class="drama-poster-cell" src="'+d.poster+'" alt=""><div><div class="drama-title-cell">'+(lang==="zh"?d.titleZh:d.title)+'</div><div class="drama-genres">'+(lang==="zh"?d.genresZh.join("/"):d.genres.join("/"))+'</div></div></div></td>';
      h+='<td><span class="type-badge '+typeBadge+'">'+typeLabel+'</span></td>';
      h+='<td>'+(lang==="zh"?d.genresZh.join(","):d.genres.join(","))+'</td>';
      h+='<td>'+d.episodes+'</td>';
      h+='<td>'+(d.views/1000).toFixed(0)+'K</td>';
      h+='<td>'+["west","arab","asia"].map(function(reg){return '<span class="region-badge '+d.regions[reg]+'">'+t(reg)+':'+t(d.regions[reg])+'</span>'}).join(" ")+'</td>';
      h+='<td>';
      if(d.uploadStatus==="approved")h+='<span class="upload-status-badge approved">✓ '+t("approved")+'</span> ';
      h+='<button class="btn small" onclick="openUploadDrama('+d.id+')">📤 '+t("uploadVideo")+'</button> <button class="btn small primary" onclick="openPushDrama('+d.id+')">🚀 '+t("push")+'</button></td></tr>';
    });
    h+='</tbody></table></div>';
  });
  return h;
}

// ===== COMPLIANCE =====
function renderCompliance(){
  var h='<div class="region-tabs">';
  ["west","arab","asia"].forEach(function(r){
    h+='<div class="region-tab '+(currentRegion===r?"active":"")+'" data-region="'+r+'" onclick="switchRegion(this.dataset.region)"><span class="region-dot '+r+'"></span>'+t("region"+r.charAt(0).toUpperCase()+r.slice(1))+'</div>';
  });
  h+='</div>';
  var c=COMPLIANCE[currentRegion];
  var boxCls=currentRegion==="arab"?"warning":"safe";
  h+='<div class="compliance-box '+boxCls+'"><div class="compliance-title">'+(currentRegion==="arab"?"⚠️":"📋")+" "+t("strictRules")+" — "+c.name[lang]+'</div><ul class="compliance-list">'+c.rules.map(function(r){return "<li>"+r[lang]+"</li>"}).join("")+'</ul></div>';
  h+='<div class="compliance-box safe"><div class="compliance-title">✓ '+t("safeContent")+" — "+c.name[lang]+'</div><ul class="compliance-list">'+c.safe.map(function(r){return "<li>"+r[lang]+"</li>"}).join("")+"</ul></div>";
  h+='<div class="card"><div class="card-header"><div class="card-title">'+t("allRegions")+" "+t("dramaLibrary")+'</div></div><table class="drama-table"><thead><tr><th>'+t("dramaName")+'</th><th>'+t("genres")+'</th><th>'+t("status")+'</th><th>'+t("actions")+'</th></tr></thead><tbody>';
  var filtered=DRAMAS.filter(function(d){return d.regions[currentRegion]!=="blocked"});
  if(filtered.length===0){
    h+='<tr><td colspan="4" style="text-align:center;padding:32px;color:var(--text-dim);">'+t("none")+'</td></tr>';
  }else{
    filtered.forEach(function(d){
      h+='<tr><td><div style="display:flex;align-items:center;gap:6px;"><img class="drama-poster-cell" src="'+d.poster+'" alt=""><div><div class="drama-title-cell">'+(lang==="zh"?d.titleZh:d.title)+'</div><div class="drama-genres">'+(lang==="zh"?d.genresZh.join("/"):d.genres.join("/"))+'</div></div></div></td><td>'+(lang==="zh"?d.genresZh.join(","):d.genres.join(","))+'</td><td><span class="status-badge '+d.regions[currentRegion]+'">'+t(d.regions[currentRegion])+'</span></td><td><button class="btn small" onclick="openCreateCampaign('+d.id+')">+ '+t("createCampaign")+'</button></td></tr>';
    });
  }
  h+='</tbody></table></div>';
  return h;
}

