// ===== UPLOAD =====
function renderUpload(){
  var h='<div class="card"><div class="card-header"><div class="card-title">'+t("uploadVideo")+'</div></div>';
  h+='<div class="upload-zone" onclick="document.getElementById(\x27fileInput\x27).click()"><div class="upload-zone-icon">📤</div><div class="upload-zone-text">'+t("dragHere")+'</div></div>';
  h+='<input type="file" id="fileInput" accept="video/*" style="display:none" onchange="handleVideoUpload(this)">';
  h+='<div class="form-group"><label class="form-label">'+t("uploadTitle")+'</label><input class="form-input" id="videoTitleInput" placeholder="Enter video title"></div>';
  h+='<div class="form-group"><label class="form-label">'+t("selectDrama")+'</label><select class="form-select" id="videoDramaSelect">'+DRAMAS.map(function(d){return '<option value="'+d.id+'">'+(lang==="zh"?d.titleZh:d.title)+'</option>'}).join("")+'</select></div>';
  h+='<div class="form-row"><div class="form-group"><label class="form-label">'+t("selectEpisode")+'</label><select class="form-select" id="episodeSelect">';
  for(var i=1;i<=30;i++)h+='<option value="'+i+'">EP'+i+'</option>';
  h+='</select></div><div class="form-group"><label class="form-label">'+t("targetRegion")+'</label><select class="form-select" id="uploadRegion"><option value="west">'+t("regionWest")+'</option><option value="arab">'+t("regionArab")+'</option><option value="asia">'+t("regionAsia")+'</option></select></div></div>';
  h+='<button class="btn primary" onclick="submitUpload()">'+t("uploadVideo")+'</button>';
  if(uploadedVideos.length>0){
    h+='<div style="margin-top:20px;"><div class="card-title" style="margin-bottom:12px;">Uploaded Videos</div>';
    uploadedVideos.forEach(function(v){h+='<div class="campaign-item"><div class="campaign-info"><div class="campaign-name">'+v.title+'</div><div class="campaign-meta"><span>Drama '+v.dramaId+'</span><span>EP'+v.episode+'</span><span class="region-badge '+v.region+'">'+t(v.region)+'</span></div></div><button class="btn small primary" onclick="startSinglePromo(\x27'+v.title+'\x27,'+v.dramaId+','+v.episode+')">'+t("singlePromo")+'</button></div>'});
    h+='</div>';
  }
  h+='</div>';
  return h;
}

