// ===== RECHARGE FLOW =====
function startRechargeFlow(){
  rechargeState.accepted=true;
  render();
  setTimeout(function(){showVerifyCodeModal()},100);
}
function rejectRecharge(){
  showToast(lang==="zh"?"已拒绝充值":"Recharge rejected","error");
  rechargeState.accepted=false;
  render();
}
function showVerifyCodeModal(){
  var body='<div style="text-align:center;padding:10px 0;">';
  body+='<div style="width:56px;height:56px;background:var(--accent);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;color:#fff;margin:0 auto 12px;">📱</div>';
  body+='<div style="font-size:15px;font-weight:600;margin-bottom:6px;">'+t("enterVerifyCode")+'</div>';
  body+='<div style="font-size:12px;color:var(--text-dim);margin-bottom:16px;">'+t("verifyCodeHint")+'</div>';
  body+='<input class="form-input" id="verifyCodeInput" type="text" maxlength="4" placeholder="'+t("verifyCodePlaceholder")+'" style="text-align:center;font-size:24px;letter-spacing:8px;width:200px;margin:0 auto;display:block;font-weight:700;" oninput="this.value=this.value.replace(/[^0-9]/g,\'\')">';
  body+='</div>';
  document.getElementById("modalTitle").textContent=t("enterVerifyCode");
  document.getElementById("modalBody").innerHTML=body;
  document.getElementById("modalFooter").innerHTML='<button class="btn" onclick="closeModal();rechargeState.accepted=false;render();">'+t("cancel")+'</button><button class="btn primary" onclick="submitVerifyCode()">'+t("generate")+'</button>';
  document.getElementById("modalOverlay").classList.add("active");
  setTimeout(function(){document.getElementById("verifyCodeInput").focus()},200);
}
function submitVerifyCode(){
  var code=document.getElementById("verifyCodeInput").value;
  if(!code||code.length!==4){showToast(lang==="zh"?"请输入4位验证码":"Please enter 4-digit code","error");return}
  rechargeState.verified=true;
  closeModal();
  render();
  setTimeout(function(){showKeyPasswordModal()},100);
}
function showKeyPasswordModal(){
  var body='<div style="text-align:center;padding:10px 0;">';
  body+='<div style="width:56px;height:56px;background:var(--gold);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;color:#fff;margin:0 auto 12px;">🔑</div>';
  body+='<div style="font-size:15px;font-weight:600;margin-bottom:6px;">'+t("enterKeyPassword")+'</div>';
  body+='<div style="font-size:12px;color:var(--text-dim);margin-bottom:16px;">'+t("keyPasswordHint")+'</div>';
  body+='<input class="form-input" id="keyPasswordInput" type="password" placeholder="'+t("keyPasswordPlaceholder")+'" style="text-align:center;width:280px;margin:0 auto;display:block;font-size:16px;letter-spacing:2px;">';
  body+='</div>';
  document.getElementById("modalTitle").textContent=t("enterKeyPassword");
  document.getElementById("modalBody").innerHTML=body;
  document.getElementById("modalFooter").innerHTML='<button class="btn" onclick="closeModal();rechargeState.verified=false;render();">'+t("cancel")+'</button><button class="btn primary" onclick="submitKeyPassword()">'+t("generate")+'</button>';
  document.getElementById("modalOverlay").classList.add("active");
  setTimeout(function(){document.getElementById("keyPasswordInput").focus()},200);
}
function submitKeyPassword(){
  var pwd=document.getElementById("keyPasswordInput").value;
  if(!pwd||pwd.length<4){showToast(lang==="zh"?"请输入Key码密码":"Please enter Key password","error");return}
  rechargeState.keyVerified=true;
  closeModal();
  render();
  showToast(t("rechargeSuccess"),"success");
}
function transferToOperate(){
  if(!rechargeState.keyVerified)return;
  if(!confirm(t("transferConfirm")))return;
  rechargeState.transferred=true;
  // Update balance
  var els=document.querySelectorAll(".balance-amount");
  var newBal=(310993.30+10086.45).toFixed(2);
  els.forEach(function(el){el.textContent="$"+newBal});
  showToast(t("transferSuccess"),"success");
  render();
}

