function renderEmail(){
  var h='';
  var sentEmails=loadEmails();
  h+='<div class="card" style="margin-bottom:6px;border-left:3px solid var(--accent);"><div class="card-header" style="margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;"><div class="card-title">📧 企业邮件 <span style="font-size:10px;color:var(--text-dim);font-weight:400;">· mana526@dingtalk.com</span></div><span style="font-size:9px;color:var(--green);background:rgba(0,168,112,.1);padding:3px 8px;border-radius:4px;">🟢 已连接</span></div>';
  // Compose form
  h+='<div style="background:var(--hover-bg);border-radius:6px;padding:10px;margin-bottom:10px;"><div style="font-size:12px;font-weight:600;color:var(--accent);margin-bottom:8px;">✉️ 写邮件</div>';
  h+='<div style="display:grid;grid-template-columns:80px 1fr;gap:6px;margin-bottom:6px;align-items:center;"><div style="font-size:11px;color:var(--text-dim);">发件人</div><div style="font-size:11px;font-weight:600;color:var(--blue);">mana526@dingtalk.com</div></div>';
  h+='<div style="display:grid;grid-template-columns:80px 1fr;gap:6px;margin-bottom:6px;align-items:center;"><div style="font-size:11px;color:var(--text-dim);">收件人</div><select id="emailTo" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;font-size:11px;background:var(--card-bg);"><option value=\"Elias Thornton <elias.thornton@dingtalk.com>\">@Elias Thornton</option><option value=\"Nolan Kim <nolan.kim@dingtalk.com>\">@Nolan Kim</option></select></div>';
  h+='<div style="display:grid;grid-template-columns:80px 1fr;gap:6px;margin-bottom:6px;align-items:center;"><div style="font-size:11px;color:var(--text-dim);">主题</div><input id="emailSubject" type="text" placeholder="输入邮件主题..." style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;font-size:11px;background:var(--card-bg);"></div>';
  h+='<div style="display:grid;grid-template-columns:80px 1fr;gap:6px;margin-bottom:8px;align-items:start;"><div style="font-size:11px;color:var(--text-dim);padding-top:6px;">正文</div><textarea id="emailBody" rows="6" placeholder="输入邮件内容..." style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;font-size:11px;background:var(--card-bg);resize:vertical;"></textarea></div>';
  h+='<div style="display:flex;gap:6px;justify-content:flex-end;"><button class="btn small" style="background:var(--hover-bg);" onclick="clearEmailForm()">清空</button><button class="btn small primary" onclick="sendEmail()">📤 发送并保存</button></div>';
  h+='</div>';
  // Sent emails list
  h+='<div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:6px;">📨 已发送邮件 ('+sentEmails.length+')</div>';
  if(sentEmails.length===0){
    h+='<div style="text-align:center;padding:20px;color:var(--text-dim);font-size:11px;">暂无已发送邮件</div>';
  }else{
    h+='<table class="drama-table" style="font-size:10px;"><thead><tr style="background:#1a1a2e;color:#fff;"><th style="padding:5px 6px;">时间</th><th>方向</th><th>发件人</th><th>收件人</th><th>主题</th><th>状态</th><th>操作</th></tr></thead><tbody>';
    sentEmails.forEach(function(e,i){
      var bg=i%2===0?"#fff":"#f8f9fa";
      var dir=e.direction||'outbound';var dirIcon=dir==='inbound'?'📥':'📤';var dirColor=dir==='inbound'?'var(--blue)':'var(--green)';var dirText=dir==='inbound'?'收件':'发件';h+='<tr style="background:'+bg+';"><td style="font-family:monospace;font-size:9px;padding:4px 6px;">'+e.time+'</td><td style="text-align:center;padding:4px 6px;"><span style="color:'+dirColor+';font-size:11px;">'+dirIcon+'</span></td><td style="padding:4px 6px;font-size:9px;color:var(--text-dim);">'+e.from+'</td><td style="padding:4px 6px;font-size:9px;">'+e.to+'</td><td style="padding:4px 6px;font-weight:600;">'+e.subject+'</td><td style="text-align:center;"><span style="background:rgba(0,168,112,.12);color:var(--green);font-size:9px;font-weight:600;padding:2px 6px;border-radius:3px;">✅ '+dirText+'</span></td><td style="text-align:center;"><span style="cursor:pointer;color:var(--accent);font-size:10px;" onclick="viewEmail('+i+')">👁</span></td></tr>';
    });
    h+='</tbody></table>';
  }
  h+='</div>';
  return h;
}
function loadEmails(){
  var user=loadUserEmails();
  var all=PRELOADED_EMAILS.concat(user);
  // Sort by time descending
  all.sort(function(a,b){return b.time.localeCompare(a.time)});
  return all;
}
function loadUserEmails(){try{return JSON.parse(localStorage.getItem("drama_emails")||"[]")}catch(e){return[]}}
function getUserEmailCount(){return loadUserEmails().length}
function saveEmails(arr){localStorage.setItem("drama_emails",JSON.stringify(arr))}
function sendEmail(){
  var toSel=document.getElementById("emailTo");var to=toSel.options[toSel.selectedIndex].text;var toAddr=toSel.value;
  var subject=document.getElementById("emailSubject").value.trim();
  var body=document.getElementById("emailBody").value.trim();
  if(!subject){showToast("请输入邮件主题","error");return}
  if(!body){showToast("请输入邮件内容","error");return}
  var now=new Date();var ts=now.getFullYear()+"-"+String(now.getMonth()+1).padStart(2,"0")+"-"+String(now.getDate()).padStart(2,"0")+" "+String(now.getHours()).padStart(2,"0")+":"+String(now.getMinutes()).padStart(2,"0")+":"+String(now.getSeconds()).padStart(2,"0");
  var emails=loadUserEmails();
  emails.unshift({time:ts,from:"MANA <mana526@dingtalk.com>",to:to,toAddr:toAddr,subject:subject,body:body,status:"sent",direction:"outbound"});
  saveEmails(emails);
  document.getElementById("emailSubject").value="";document.getElementById("emailBody").value="";
  showToast("✅ 邮件已发送至 "+to+" 并自动保存","success");
  render();
}
function clearEmailForm(){document.getElementById("emailSubject").value="";document.getElementById("emailBody").value=""}
function viewEmail(idx){
  var emails=loadEmails();var e=emails[idx];if(!e)return;
  var html='<div style="font-size:11px;line-height:1.8;"><div style="margin-bottom:6px;"><b>From:</b>'+e.from+'</div><div style="margin-bottom:6px;"><b>To:</b>'+e.to+'</div><div style="margin-bottom:6px;"><b>Date:</b>'+e.time+'</div><div style="margin-bottom:6px;"><b>Subject:</b>'+e.subject+'</div><hr style="border:none;border-top:1px solid var(--border);margin:8px 0;"><div style="white-space:pre-wrap;">'+e.body+'</div></div>';
  document.getElementById("modalTitle").textContent="📧 邮件详情";
  document.getElementById("modalBody").innerHTML=html;
  document.getElementById("modalFooter").innerHTML='<button class="btn" onclick="closeModal()">关闭</button>';
  document.getElementById("modalOverlay").classList.add("active");
}

