        csv+=","+ddd[0]+","+ddd[1]+","+ddd[2]+","+(ddd[2]>0?(ddd[1]/ddd[2]).toFixed(2):"-");
        dayImpr+=ddd[0];daySpend+=ddd[1];dayConv+=ddd[2];
